// Verifies the HMAC the VizIntel notifier puts on every webhook:
//   X-VizIntel-Signature = "sha256=" + HMAC_SHA256(secret, timestamp + "." + body)
// and rejects timestamps older than 5 minutes (replay protection).
const crypto = require('crypto');
const secret = $env.VIZINTEL_WEBHOOK_SECRET || '';

return $input.all().map((item) => {
  const headers = item.json.headers || {};
  const body = item.json.body || {};
  const signature = String(headers['x-vizintel-signature'] || '');
  const timestamp = String(headers['x-vizintel-timestamp'] || '');
  const fresh = Math.abs(Date.now() - Number(timestamp)) < 5 * 60 * 1000;
  const expected = 'sha256=' + crypto.createHmac('sha256', secret)
    .update(timestamp + '.' + JSON.stringify(body))
    .digest('hex');
  const valid = Boolean(secret) && fresh && signature.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  const reason = valid ? null : !secret ? 'VIZINTEL_WEBHOOK_SECRET not configured' : !fresh ? 'stale or missing timestamp' : 'invalid signature';
  return { json: { valid, reason, event: body } };
});

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (n) => (typeof n === 'number' && Number.isFinite(n)) ? n.toLocaleString('en-US', { maximumFractionDigits: 2 }) : esc(n);
const layout = (title, body) => `<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;color:#0f172a">
  <div style="background:#4f46e5;color:#fff;padding:20px 24px;border-radius:12px 12px 0 0"><b style="font-size:18px">VizIntel Dashboard</b></div>
  <div style="border:1px solid #e2e8f0;border-top:0;padding:24px;border-radius:0 0 12px 12px">
    <h2 style="margin:0 0 12px;font-size:20px">${title}</h2>${body}
  </div>
  <p style="color:#94a3b8;font-size:12px;text-align:center;margin-top:12px">Automated message from the VizIntel n8n workflows.</p>
</div>`;
const button = (href, label) => `<p style="margin:20px 0 0"><a href="${esc(href)}" style="background:#4f46e5;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">${esc(label)}</a></p>`;

return $input.all().map((item) => {
  const e = item.json.event;
  const d = e.dataset;
  const status = {
    ready: 'AI insights are ready on your dashboard.',
    pending: 'AI insights are being generated in the background — you will get another email when they are ready.',
    failed: 'AI insights could not be generated yet. We are retrying automatically.',
  }[d.insightsStatus] || '';
  const rows = (d.topKpis || []).map((k) => `<tr>
      <td style="padding:6px 10px;border-bottom:1px solid #e2e8f0">${esc(k.name)}</td>
      <td style="padding:6px 10px;border-bottom:1px solid #e2e8f0;text-align:right"><b>${fmt(k.sum)}</b></td>
      <td style="padding:6px 10px;border-bottom:1px solid #e2e8f0;text-align:right">${fmt(Number(k.avg))}</td></tr>`).join('');
  const kpiTable = rows ? `<table style="border-collapse:collapse;width:100%;font-size:14px;margin:12px 0">
      <tr style="background:#f1f5f9"><th style="text-align:left;padding:6px 10px">KPI</th><th style="text-align:right;padding:6px 10px">Total</th><th style="text-align:right;padding:6px 10px">Avg / row</th></tr>${rows}</table>` : '';
  const body = `<p>Hi ${esc(e.user.name)},</p>
    <p><b>${esc(d.name)}</b> has been analysed: <b>${fmt(d.rowCount)}</b> rows, <b>${fmt(d.columnCount)}</b> columns,
    ${fmt(d.kpiCount)} KPIs and ${fmt(d.chartCount)} charts generated in ${fmt(d.processingMs)} ms.</p>
    ${kpiTable}<p>${esc(status)}</p>${button(d.url, 'Open dashboard')}`;
  return { json: { to: e.user.email, subject: `Your dataset "${d.name}" has been processed`, html: layout('Dataset processed', body), event: e } };
});
